import{_ as a}from"./chunks/第一步-03.D7lAR9Hu.js";import{_ as r,o,c as t,a2 as l}from"./chunks/framework.CqGPl1zp.js";const d="/newx-doc/assets/%E5%BC%95%E5%85%A5%E6%A8%A1%E5%9D%9701.DlWjj2t6.png",s="/newx-doc/assets/%E5%BC%95%E5%85%A5%E6%A8%A1%E5%9D%9702.DDTLKCnQ.png",i="/newx-doc/assets/%E7%AE%A1%E7%90%86%E5%90%8E%E5%8F%B0.D4DVCwKs.png",q=JSON.parse('{"title":"功能开启","description":"","frontmatter":{},"headers":[],"relativePath":"member/build.md","filePath":"member/build.md","lastUpdated":null}'),p={name:"member/build.md"};function m(n,e,c,u,h,_){return o(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="功能开启" tabindex="-1">功能开启 <a class="header-anchor" href="#功能开启" aria-label="Permalink to &quot;功能开启&quot;">​</a></h1><h2 id="_1-概述" tabindex="-1">1. 概述 <a class="header-anchor" href="#_1-概述" aria-label="Permalink to &quot;1. 概述&quot;">​</a></h2><p>会员中心，围绕“会员”建设，包括会员用户、VIP 等级、经验、积分、签到等一系列的功能。</p><p>疑问：什么是会员？</p><p>对于管理系统来说，管理员是它的用户，也就是项目中的 <code>system_users</code> 表</p><p>而对于商城、论坛、博客等前台系统来说，会员是它的用户，也就是会员中心的 <code>member_user</code> 表。</p><h2 id="_2-后端启动" tabindex="-1">2. 后端启动 <a class="header-anchor" href="#_2-后端启动" aria-label="Permalink to &quot;2. 后端启动&quot;">​</a></h2><p>考虑到编译速度，默认 <code>yudao-module-member</code> 模块是关闭的，需要手动开启。步骤如下：</p><ul><li>第一步，开启 <code>yudao-module-member</code> 模块</li><li>第二步，导入会员的 SQL 数据库脚本</li><li>第三步，重启后端项目，确认功能是否生效</li></ul><h3 id="_2-1-开启模块" tabindex="-1">2.1 开启模块 <a class="header-anchor" href="#_2-1-开启模块" aria-label="Permalink to &quot;2.1 开启模块&quot;">​</a></h3><p>① 修改根目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，取消 <code>yudao-module-member</code> 模块的注释。如下图所示：</p><p><img src="'+d+'" alt="取消  模块的注释"></p><p>② 修改 <code>yudao-server</code> 目录的 <a href="https://github.com/YunaiV/ruoyi-vue-pro/blob/master/yudao-server/pom.xml" target="_blank" rel="noreferrer"><code>pom.xml</code></a> 文件，引入 <code>yudao-module-member</code> 模块。如下图所示：</p><p><img src="'+s+'" alt="引入  模块"></p><p>③ 点击 IDEA 右上角的【Reload All Maven Projects】，刷新 Maven 依赖。如下图所示：</p><p><img src="'+a+'" alt="刷新 Maven 依赖"></p><h3 id="_2-2-第二步-导入-sql" tabindex="-1">2.2 第二步，导入 SQL <a class="header-anchor" href="#_2-2-第二步-导入-sql" aria-label="Permalink to &quot;2.2 第二步，导入 SQL&quot;">​</a></h3><p>点击 <a href="https://lwb8832652.github.io/newx-doc/sql/member.sql" target="_blank" rel="noreferrer">下载 SQL</a> 直接下载 SQL 文件，导入到数据库中。</p><p>友情提示：↑↑↑ member.sql 是可以点击下载的！ ↑↑↑</p><p>重要说明：该 SQL 仅芋道星球成员可使用和商用，否则视为侵权（索赔 100 万，永久追溯）【下载即视为同意】。</p><h3 id="_2-3-第三步-重启项目" tabindex="-1">2.3 第三步，重启项目 <a class="header-anchor" href="#_2-3-第三步-重启项目" aria-label="Permalink to &quot;2.3 第三步，重启项目&quot;">​</a></h3><p>重启后端项目，然后访问前端的会员菜单，确认功能是否生效。如下图所示：</p><p><img src="'+i+'" alt="确认功能是否生效"></p><p>至此，我们就成功开启了会员中心的功能 🙂</p><h2 id="_3-前端-商城-启动" tabindex="-1">3. 前端（商城）启动 <a class="header-anchor" href="#_3-前端-商城-启动" aria-label="Permalink to &quot;3. 前端（商城）启动&quot;">​</a></h2><p>可阅读 <a href="./../mall/build">《商城 - 功能开启》</a> 文档，目前商城 uni-app 接入会员中心进行购物。</p>',26)])])}const x=r(p,[["render",m]]);export{q as __pageData,x as default};
